<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$posts=(array)($inbox['posts']??[]);$conversations=(array)($inbox['conversations']??[]);?>
<style>.inbox-toolbar,.inbox-tabs{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.inbox-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.inbox-list{display:grid;gap:12px}.inbox-item{padding:14px;border:1px solid #dfe7ef;border-radius:14px;background:#fff}.inbox-item p{white-space:pre-wrap}.inbox-reply{display:flex;gap:8px;margin-top:10px}.inbox-reply textarea{flex:1;min-height:60px}@media(max-width:900px){.inbox-grid{grid-template-columns:1fr}}</style>
<section class="panel"><div class="panel-head"><div><h2>Messages et commentaires</h2><p class="panel-subtitle">Lisez les échanges des Pages Facebook connectées et répondez sans quitter Strax.</p></div></div>
<form method="get" class="inbox-toolbar"><label>Page<select name="connection_id" onchange="this.form.submit()"><option value="">Choisir une Page</option><?php foreach($connections as$c):?><option value="<?= (int)$c['id']?>" <?= (int)$selected===(int)$c['id']?'selected':''?>><?= $e($c['account_label'])?></option><?php endforeach?></select></label><noscript><button class="button" type="submit">Afficher</button></noscript></form></section>
<?php if($error):?><div class="flash error"><?= $e($error)?></div><?php endif?>
<div class="inbox-grid"><section class="panel"><h2>Commentaires</h2><div class="inbox-list"><?php if(!$posts):?><p>Aucun commentaire récent retourné.</p><?php endif?><?php foreach($posts as$post):foreach((array)($post['comments']['data']??[])as$comment):?><article class="inbox-item"><small><?= $e(($comment['from']['name']??'Utilisateur').' · '.($comment['created_time']??''))?></small><p><?= $e($comment['message']??'')?></p><?php if($canReply):?><form method="post" action="<?= $e(route_url('/social-inbox/reply-comment'))?>" class="inbox-reply"><input type="hidden" name="connection_id" value="<?= (int)$selected?>"><input type="hidden" name="comment_id" value="<?= $e($comment['id']??'')?>"><textarea name="message" required placeholder="Répondre au commentaire…"></textarea><button class="button" type="submit">Répondre</button></form><?php endif?></article><?php endforeach;endforeach?></div></section>
<section class="panel"><h2>Messages privés</h2><?php if(!empty($inbox['message_error'])):?><div class="flash info"><?= $e($inbox['message_error'])?></div><?php endif?><div class="inbox-list"><?php if(!$conversations):?><p>Aucune conversation récente retournée.</p><?php endif?><?php foreach($conversations as$conversation):$participants=(array)($conversation['participants']['data']??[]);$recipient='';foreach($participants as$p)if((string)($p['id']??'')!==(string)($inbox['connection']['external_account_id']??'')){$recipient=(string)$p['id'];break;}?><article class="inbox-item"><?php foreach(array_reverse((array)($conversation['messages']['data']??[]))as$message):?><small><?= $e(($message['from']['name']??'Utilisateur').' · '.($message['created_time']??''))?></small><p><?= $e($message['message']??'')?></p><?php endforeach?><?php if($canReply&&$recipient!==''):?><form method="post" action="<?= $e(route_url('/social-inbox/reply-message'))?>" class="inbox-reply"><input type="hidden" name="connection_id" value="<?= (int)$selected?>"><input type="hidden" name="recipient_id" value="<?= $e($recipient)?>"><textarea name="message" required placeholder="Répondre au message…"></textarea><button class="button" type="submit">Envoyer</button></form><?php endif?></article><?php endforeach?></div></section></div>
